import{_ as d,o as e,c as o,a6 as c}from"./chunks/framework.B_q3ZJNF.js";const s=JSON.parse('{"title":"SQL 常用语法速查表","description":"","frontmatter":{"title":"SQL 常用语法速查表"},"headers":[],"relativePath":"sql-orm-course/sql-cheatsheet.md","filePath":"sql-orm-course/docs/sql-cheatsheet.md"}'),r={name:"sql-orm-course/sql-cheatsheet.md"};function a(h,t,E,L,N,l){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="sql-常用语法速查表" tabindex="-1">SQL 常用语法速查表 <a class="header-anchor" href="#sql-常用语法速查表" aria-label="Permalink to &quot;SQL 常用语法速查表&quot;">​</a></h1><p>全书教过的 SQL 语法一览，以 SQLite 为准；方言列标注 MySQL（MySQL）/PostgreSQL（PG）的差异。只列本书教过的写法——各条的正文的演算与断言见括号里的章号。</p><h2 id="建表与约束-ddl" tabindex="-1">建表与约束（DDL） <a class="header-anchor" href="#建表与约束-ddl" aria-label="Permalink to &quot;建表与约束（DDL）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语法</th><th>作用</th><th>备注</th></tr></thead><tbody><tr><td><code>CREATE TABLE 表名 (列名 类型 约束, …);</code></td><td>把形状说出口（第 1、3 章）</td><td>列定义 = 名字 + 类型 + 可选约束串</td></tr><tr><td><code>INTEGER PRIMARY KEY</code></td><td>主键：行的身份证号（第 3 章）</td><td>SQLite 里它是隐藏行号 rowid 的别名</td></tr><tr><td><code>INTEGER PRIMARY KEY AUTOINCREMENT</code></td><td>发号只增不减、删号不复用（第 3 章）</td><td>通常不需要；MySQL 写 <code>AUTO_INCREMENT</code>，PG 写 <code>SERIAL</code> 或 <code>GENERATED … AS IDENTITY</code></td></tr><tr><td><code>NOT NULL</code></td><td>这列不许为空（第 3 章）</td><td></td></tr><tr><td><code>UNIQUE</code></td><td>这列全表不得重复（第 3 章）</td><td>SQLite 实现自带一本自动目录</td></tr><tr><td><code>DEFAULT 值</code></td><td>插入不给这列时自动补（第 3 章）</td><td>字符串字面量要引号</td></tr><tr><td><code>REFERENCES 表(列)</code></td><td>外键：指向另一张表某行的主键（第 3 章）</td><td>SQLite 默认不执法，要 <code>PRAGMA foreign_keys = ON</code>；MySQL（InnoDB）与 PG 建了就强制</td></tr><tr><td><code>CREATE INDEX idx_表_列 ON 表(列);</code> / <code>CREATE INDEX … ON 表(列1, 列2);</code></td><td>建目录 / 联合目录（第 6 章）</td><td>联合索引守最左前缀：条件从最左列连续成段，段内最后一列才许范围</td></tr><tr><td><code>DROP INDEX 索引名;</code> / <code>DROP TABLE 表名;</code></td><td>拆目录 / 拆整张表（第 6、3 章）</td><td>DELETE FROM 只删行，DROP TABLE 连房子一起拆</td></tr></tbody></table><p>类型：<code>TEXT</code>（文本）、<code>INTEGER</code>（整数）、<code>REAL</code>（小数）——SQLite 没有布尔与日期类型（取舍见第 9 章与<a href="./orm-divergence.html">差异清单</a>）。SQLite 的类型是建议，MySQL/PG 的类型是法律。</p><h2 id="查询-dml" tabindex="-1">查询（DML） <a class="header-anchor" href="#查询-dml" aria-label="Permalink to &quot;查询（DML）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语法</th><th>作用</th><th>备注</th></tr></thead><tbody><tr><td><code>SELECT 列1, 列2 FROM 表;</code></td><td>锁行取列（第 1 章）</td><td><code>*</code> 表示所有列全要</td></tr><tr><td><code>WHERE 条件</code></td><td>筛行（第 2 章）</td><td>比较符 <code>= != &gt; &lt; &gt;= &lt;=</code> 与 JS 几乎一致</td></tr><tr><td><code>AND</code> / <code>OR</code> / <code>NOT</code></td><td>组合条件（第 2 章）</td><td>AND 优先级高于 OR，拿不准加括号</td></tr><tr><td><code>IN (&#39;a&#39;, &#39;b&#39;)</code></td><td>值在候选清单里（第 2 章）</td><td></td></tr><tr><td><code>BETWEEN a AND b</code></td><td>闭区间，两端都算（第 2 章）</td><td>等价 <code>&gt;= a AND &lt;= b</code></td></tr><tr><td><code>LIKE &#39;a%&#39;</code> / <code>&#39;_b&#39;</code></td><td>模糊匹配：% 任意长度、_ 恰一个字符（第 2 章）</td><td>SQLite 默认只对 ASCII 不分大小写；PG 区分（不区分用 ILIKE）；前导通配走不了索引</td></tr><tr><td><code>IS NULL</code> / <code>IS NOT NULL</code></td><td>查空 / 查非空（第 2 章）</td><td><code>= NULL</code> 永远查不出任何行——NULL 比较得 UNKNOWN</td></tr><tr><td><code>ORDER BY 列 DESC, 列2 ASC</code></td><td>排序，多列各带方向（第 2 章）</td><td>业务列在前、主键兜底在后，分页才不重不漏</td></tr><tr><td><code>LIMIT n OFFSET m</code></td><td>分页：取 n 行、先跳 m 行（第 2 章）</td><td><code>OFFSET = (页码−1) × 每页行数</code>；MySQL 另有逗号版 <code>LIMIT m, n</code>（先跳后取，别记混）</td></tr><tr><td><code>AS 别名</code></td><td>给列或表起短名（第 4、5 章）</td><td>WHERE 用别名 MySQL/PG 不认、SQLite 宽容但未承诺——跨库别用</td></tr></tbody></table><h2 id="聚合与分组" tabindex="-1">聚合与分组 <a class="header-anchor" href="#聚合与分组" aria-label="Permalink to &quot;聚合与分组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语法</th><th>作用</th><th>备注</th></tr></thead><tbody><tr><td><code>COUNT(*)</code> / <code>COUNT(列)</code></td><td>数行 / 只数有值的格子（第 4 章）</td><td>差额就是该列为 NULL 的行数</td></tr><tr><td><code>SUM</code> / <code>AVG</code> / <code>MIN</code> / <code>MAX</code></td><td>求和 / 平均 / 最小 / 最大（第 4 章）</td><td>全部跳过 NULL；全空时 SUM、AVG 出 NULL</td></tr><tr><td><code>GROUP BY 列</code></td><td>按列的值分桶，每桶出一行（第 4 章）</td><td>SELECT 里只放分组列和聚合表达式（裸列是 SQLite 的宽容扩展）</td></tr><tr><td><code>HAVING 组条件</code></td><td>分组后筛组（第 4 章）</td><td>WHERE 筛行在先、HAVING 筛组在后；条件带聚合函数必是组条件</td></tr></tbody></table><h2 id="多表" tabindex="-1">多表 <a class="header-anchor" href="#多表" aria-label="Permalink to &quot;多表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语法</th><th>作用</th><th>备注</th></tr></thead><tbody><tr><td><code>FROM a INNER JOIN b ON a.x = b.y</code></td><td>只留两边都配得上的行（第 5 章）</td><td>一对多时左行会重复出现</td></tr><tr><td><code>FROM a LEFT JOIN b ON …</code></td><td>保左表全量，配不上的右列补 NULL（第 5 章）</td><td>行数 ≥ INNER 版，差额正是配不上的左行数</td></tr><tr><td><code>表别名</code>（<code>users u</code>）与 <code>u.列</code> 前缀</td><td>消歧（第 5 章）</td><td>连接条件写 ON、筛选条件写 WHERE；LEFT 下对右表列的 WHERE 会把保左打回 INNER</td></tr><tr><td><code>FROM a, b WHERE …</code>（逗号老写法）</td><td>等价内连接（第 5 章）</td><td>忘写条件即叉积；新代码一律 JOIN … ON</td></tr></tbody></table><h2 id="写操作" tabindex="-1">写操作 <a class="header-anchor" href="#写操作" aria-label="Permalink to &quot;写操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语法</th><th>作用</th><th>备注</th></tr></thead><tbody><tr><td><code>INSERT INTO 表 (列…) VALUES (?, …);</code></td><td>放一行进去（第 1 章）</td><td>值永远走占位符参数，不拼字符串（第 8 章）</td></tr><tr><td><code>UPDATE 表 SET 列 = ? WHERE …;</code></td><td>改行（第 3 章）</td><td>省略 WHERE = 全表都是目标；changes 回执告诉你改了几行</td></tr><tr><td><code>DELETE FROM 表 WHERE …;</code></td><td>删行（第 3 章）</td><td>同上，省略 WHERE 清空整表</td></tr></tbody></table><h2 id="事务与工具" tabindex="-1">事务与工具 <a class="header-anchor" href="#事务与工具" aria-label="Permalink to &quot;事务与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语法</th><th>作用</th><th>备注</th></tr></thead><tbody><tr><td><code>BEGIN;</code> / <code>COMMIT;</code> / <code>ROLLBACK;</code></td><td>开事务 / 一次生效 / 全部作废（第 13 章）</td><td>圈进来的语句捆绑成败；性能是副产品</td></tr><tr><td><code>EXPLAIN QUERY PLAN 语句</code></td><td>让数据库交代执行方案（第 6 章）</td><td>SCAN 整表逐行、SEARCH 只碰一部分；MySQL/PG 用 <code>EXPLAIN</code>（PG 另有 <code>EXPLAIN ANALYZE</code>）</td></tr><tr><td><code>PRAGMA foreign_keys = ON;</code></td><td>打开外键执法（第 3 章）</td><td>每个连接都要手动开；事务中途改它是空操作</td></tr></tbody></table><p>安全铁律：用户输入永远走 <code>?</code> 占位符 + 参数绑定（第 8 章）；进不了参数通道的只有标识符（列名、表名）与结构（占位符个数），它们只能拼，且必须过白名单（第 10、12 章）。</p>',16)])])}const b=d(r,[["render",a]]);export{s as __pageData,b as default};
